const themeButtons=[...document.querySelectorAll('[data-theme-choice]')];
function syncThemeButtons(){themeButtons.forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.themeChoice===document.documentElement.dataset.theme)))}
syncThemeButtons();
themeButtons.forEach(button=>button.addEventListener('click',()=>{const theme=button.dataset.themeChoice;document.documentElement.dataset.theme=theme;try{localStorage.setItem('six7-theme',theme)}catch(e){}syncThemeButtons();const meta=document.querySelector('meta[name="theme-color"]');if(meta)meta.content=theme==='light'?'#f4f2eb':'#242527'}));
window.addEventListener('storage',event=>{if(event.key==='six7-theme'&&(event.newValue==='light'||event.newValue==='dark')){document.documentElement.dataset.theme=event.newValue;syncThemeButtons()}});

const data=JSON.parse(document.getElementById('app-data').textContent);const tabs=[...document.querySelectorAll('[role="tab"]')];function activate(index,focus=false){tabs.forEach((tab,i)=>{tab.setAttribute('aria-selected',String(i===index));tab.tabIndex=i===index?0:-1});document.getElementById('app-panel').setAttribute('aria-labelledby','tab-'+index);document.getElementById('app-name').textContent=data.names[index];document.getElementById('app-desc').textContent=data.descriptions[index];document.getElementById('app-sub').textContent=data.sub[index];document.getElementById('app-scope').textContent='0'+(index+1)+' / '+data.scope;if(focus)tabs[index].focus()}tabs.forEach((tab,i)=>{tab.addEventListener('click',()=>activate(i));tab.addEventListener('keydown',e=>{let n;if(e.key==='ArrowRight')n=(i+1)%tabs.length;else if(e.key==='ArrowLeft')n=(i+tabs.length-1)%tabs.length;else if(e.key==='Home')n=0;else if(e.key==='End')n=tabs.length-1;else return;e.preventDefault();activate(n,true)})});document.querySelectorAll('.lang a').forEach(a=>{a.addEventListener('click',()=>{if(location.hash)a.hash=location.hash})});